/* Project : 2050 — service worker (offline play). Generated by web/build.mjs from web/sw.js; do not edit the copy in the site root. */
const CACHE = "__CACHE__";
const CORE = /*CORE*/[];
const ICONS = ["favicon.svg", "icon-16.png", "icon-32.png", "icon-192.png", "icon-512.png", "apple-touch-icon.png"];

self.addEventListener("install", e => {
  e.waitUntil(caches.open(CACHE).then(c => Promise.all([...CORE, ...ICONS].map(f => c.add(f).catch(() => {})))).then(() => self.skipWaiting()));
});
self.addEventListener("activate", e => {
  // keep the media cache (images / audio) between versions; drop old app shells
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith("p2050-") && k !== CACHE && k !== "p2050-media").map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
/* <audio> sends Range requests; answer them from the cached file with a 206 slice. */
async function rangeResponse(req, res){
  const m = /bytes=(\d*)-(\d*)/.exec(req.headers.get("range") || ""); if (!m) return res;
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  const start = m[1] ? +m[1] : Math.max(0, size - +m[2]), end = m[1] && m[2] ? Math.min(+m[2], size - 1) : size - 1;
  return new Response(buf.slice(start, end + 1), {status:206, statusText:"Partial Content", headers:{
    "Content-Type":res.headers.get("Content-Type") || "audio/mpeg", "Content-Range":`bytes ${start}-${end}/${size}`, "Content-Length":String(end - start + 1), "Accept-Ranges":"bytes"}});
}
self.addEventListener("fetch", e => {
  const req = e.request; if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  if (/\/(api|verify)\//.test(url.pathname)) return;          // the game server is never cached
  if (req.mode === "navigate"){
    e.respondWith((async () => {
      try { const ctl = new AbortController(), tm = setTimeout(() => ctl.abort(), 4000); const r = await fetch(req, {signal:ctl.signal}); clearTimeout(tm); if (r.ok) (await caches.open(CACHE)).put("index.html", r.clone()); return r; }
      catch { return (await caches.match("index.html")) || (await caches.match("./")) || Response.error(); }
    })());
    return;
  }
  const media = /\/assets\/(img|audio)\//.test(url.pathname);
  e.respondWith((async () => {
    const key = new Request(url.href.split("#")[0].split("?")[0]);
    const hit = await caches.match(key, {ignoreSearch:true});
    if (hit) return req.headers.has("range") ? rangeResponse(req, hit) : hit;
    try {
      const r = await fetch(req.headers.has("range") && media ? key : req);
      if (r.ok && r.status === 200){ const cp = r.clone(); caches.open(media ? "p2050-media" : CACHE).then(c => c.put(key, cp)); return req.headers.has("range") ? rangeResponse(req, r) : r; }
      return r;
    } catch { return Response.error(); }
  })());
});
